<script setup lang="ts">
import { computed } from 'vue'
import { useRoute } from 'vue-router'
import AppHeader from '../components/AppHeader.vue'
import { coreActions } from '../data/coreAbilities'
import { ruleSourceDocuments, type RuleSourceBlock, type RuleSourceSection } from '../data/rulesSource'
import diceStrip from '../assets/rules/brambleheart-dice-strip.webp'
import { useSettings } from '../state/settings'
import { formatMeasurementText } from '../rules/measurements'
import { ABILITY_TYPE_KEYWORDS, abilityPillLabel, abilityTypeClass, canonicalAbilityType } from '../rules/abilityPresentation'

const route=useRoute()
const {measurement}=useSettings()
const slug=computed(()=>String(route.params.slug||'core-rules'))
const mode=computed(()=>slug.value==='attributes-skills'?'attributes':slug.value==='abilities'?'abilities':'core')
const title=computed(()=>mode.value==='attributes'?'Attributes & Skills':mode.value==='abilities'?'Core Actions':'Core Rules')
const sourceSections=computed(()=>ruleSourceDocuments.fundamentals?.sections||[])
const ATTRIBUTE_HEADINGS=new Set(['ATTRIBUTES','RANKS & MODIFIERS','SKILLS','SKILL TREES','EXPANDED & RESTRICTED'])

function displayText(text:string){return formatMeasurementText(text,measurement.value)}
function sectionByHeading(sections:RuleSourceSection[],heading:string){return sections.find(section=>section.heading.toUpperCase()===heading)}
function isSecondaryStatsParagraph(block:RuleSourceBlock){return block.type==='paragraph'&&/^SECONDARY STATS:/i.test(block.text.trim())}
function splitTargets(section:RuleSourceSection){
  const regular:RuleSourceBlock[]=[],targets:RuleSourceBlock[]=[]
  let targetMode=false
  for(const block of section.blocks){
    if(block.type==='paragraph'&&/ACTIVE\s*&\s*PASSIVE TARGETS/i.test(block.text)){
      targetMode=true
      const text=block.text.replace(/^ACTIVE\s*&\s*PASSIVE TARGETS\s*/i,'').trim()
      if(text)targets.push({...block,text})
      continue
    }
    ;(targetMode?targets:regular).push(block)
  }
  return{regular,targets}
}
const bodySections=computed<RuleSourceSection[]>(()=>{
  const sections=sourceSections.value.filter(section=>section.heading.toLowerCase()!=='overview')
  if(mode.value==='abilities')return[]
  if(mode.value==='attributes'){
    const attributes=sectionByHeading(sections,'ATTRIBUTES')
    const ranks=sectionByHeading(sections,'RANKS & MODIFIERS')
    const skills=sectionByHeading(sections,'SKILLS')
    const trees=sectionByHeading(sections,'SKILL TREES')
    const expanded=sectionByHeading(sections,'EXPANDED & RESTRICTED')
    const out:RuleSourceSection[]=[]
    if(attributes)out.push({...attributes,blocks:attributes.blocks.filter(block=>!isSecondaryStatsParagraph(block))})
    if(ranks)out.push(ranks)
    const treeTables=(expanded?.blocks||[]).filter(block=>block.type==='table')
    if(skills||trees||treeTables.length)out.push({heading:'SKILLS',blocks:[...(skills?.blocks||[]),...(trees?.blocks||[]),...treeTables]})
    if(expanded)out.push({heading:'EXPANDED & RESTRICTED',blocks:expanded.blocks.filter(block=>block.type!=='table')})
    return out
  }
  const out:RuleSourceSection[]=[]
  for(const section of sections){
    if(ATTRIBUTE_HEADINGS.has(section.heading.toUpperCase()))continue
    if(section.heading.toUpperCase()==='EDGED & WEIGHTED ROLLS'){
      const split=splitTargets(section)
      out.push({...section,blocks:split.regular})
      if(split.targets.length)out.push({heading:'ACTIVE & PASSIVE TARGETS',blocks:split.targets})
    }else out.push(section)
  }
  return out
})

function sectionId(value:string,index:number){return`rules-${index}-${value.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'section'}`}
const targetExamples:Record<string,string>={Easy:'Routine task under light pressure',Medium:'Standard challenge with meaningful risk',Difficult:'Demanding task requiring strong skill',Hard:'Severe challenge under poor conditions','Very Hard':'Extreme feat with little margin'}
function tableRows(section:RuleSourceSection,block:RuleSourceBlock){
  if(block.type!=='table')return[]
  if(section.heading!=='ACTIVE & PASSIVE TARGETS')return block.rows
  return block.rows.map((row,index)=>index===0?[...row,'Example']:[...row,targetExamples[row[0]||'']||''])
}
function displayParagraph(section:RuleSourceSection,text:string){
  let value=displayText(text)
  if(section.heading==='HALF-STEP ROLLS'){
    if(/divide the natural \(unmodified\) dice result by two/i.test(value))return'For a half-step roll, roll 1d10 and read the die by its result band. Do not divide the die result.'
    if(/The resulting value will determine your final total/i.test(value))return'A natural d10 result of 1–5 gives a half-step result of 1. A natural d10 result of 6–10 gives a half-step result of 2.'
    if(/required to roll \[1d10\/2\+1\]/i.test(value))return'The notation [1d10/2+1] means: roll the d10, convert it to its half-step result (1 or 2), then add the listed +1 condition.'
  }
  return value
}
function displayHeading(value:string){return value.toUpperCase()==='FORTUNE & MISFORTUNE RESULTS'?'FORTUNE & MISFORTUNE':value}
function isFormulaParagraph(section:RuleSourceSection,block:RuleSourceBlock){return section.heading==='THE CORE ROLL'&&block.type==='paragraph'&&/\(3d10\)\s*\+\s*stat/i.test(block.text)}
function isHalfStepFormula(block:RuleSourceBlock){return block.type==='paragraph'&&/^\(1d10\/2\)$/i.test(block.text.trim())}
function showConditionsGraphic(section:RuleSourceSection,blockIndex:number){return section.heading==='CONDITIONS'&&blockIndex===0}
function showFortuneGraphic(section:RuleSourceSection){return section.heading==='FORTUNE & MISFORTUNE RESULTS'}
function showHalfStepExample(section:RuleSourceSection){return section.heading==='HALF-STEP ROLLS'}
function showEdgedWeightedGraphic(section:RuleSourceSection){return section.heading==='EDGED & WEIGHTED ROLLS'}
function isTargetSection(section:RuleSourceSection){return section.heading==='ACTIVE & PASSIVE TARGETS'}
function showSecondaryStatsGraphic(section:RuleSourceSection){return mode.value==='attributes'&&section.heading==='ATTRIBUTES'}
function skillTreeName(block:RuleSourceBlock){if(block.type!=='table'||block.rows.length<2)return'';const row=block.rows[1];return row.length===1&&/Skill Tree$/i.test(row[0])?displayText(row[0]):''}
function skillTreeTone(name:string){return name.toLowerCase().split(' ')[0]||'skill'}
function skillTreeRows(block:RuleSourceBlock){return block.type==='table'?block.rows.slice(2).filter(row=>row.some(cell=>String(cell).trim())):[]}
const secondaryBreakdown=[
  {name:'Agility',short:'AGI',rank:'Accuracy',modifier:'Aim',extra:'Speed = 2 + AGI modifier'},
  {name:'Might',short:'MIG',rank:'Fury',modifier:'Brawl',extra:''},
  {name:'Hide',short:'HID',rank:'Guts',modifier:'Ward',extra:''},
  {name:'Lore',short:'LOR',rank:'Power',modifier:'Control',extra:''},
  {name:'Bravery',short:'BRY',rank:'Heart',modifier:'Spirit',extra:''},
]
const coreFamilyPriority=['Instinct','Move','Touch','Shoot','Magic','Reactive','Passive']
function coreActionFamily(keywords:string[]){return coreFamilyPriority.find(family=>keywords.map(canonicalAbilityType).includes(family))||'Core'}
function coreActionCardClass(keywords:string[]){return abilityTypeClass(coreActionFamily(keywords))}
function coreActionKeywordLabel(actionName:string,keyword:string){return actionName.toUpperCase()==='REACTION'&&keyword.trim().toLowerCase()==='reaction'?'REACTION':abilityPillLabel(keyword)}
const previousPage=computed(()=>mode.value==='attributes'?{label:'Core Rules',path:'/rules/read/core-rules'}:mode.value==='abilities'?{label:'Attributes & Skills',path:'/rules/read/attributes-skills'}:null)
const nextPage=computed(()=>mode.value==='core'?{label:'Attributes & Skills',path:'/rules/read/attributes-skills'}:mode.value==='attributes'?{label:'Core Actions',path:'/rules/read/abilities'}:null)
</script>

<template>
  <main class="page fundamentals-rule-page">
    <AppHeader compact back-to="/rules" back-label="Back to Rules" prefer-back-to />
    <article class="fundamentals-rule-shell">
      <header class="fundamentals-rule-hero card-surface"><p class="eyebrow">FUNDAMENTALS</p><h1>{{ title }}</h1></header>
      <section class="fundamentals-rule-body card-surface">
        <section v-if="mode==='abilities'" class="abilities-rule-stack">
          <article id="abilities-what" class="fundamentals-rule-section"><h2>CORE ACTIONS &amp; ABILITIES</h2><p>Core Actions are the shared actions every character can take during an encounter. They establish what a character is doing and are the only starting points for an Ability Chain. A Core Action spends the matching Instinct, Move, Combat, or Reaction opportunity and resolves according to its own Trigger, Effect, and Restrictions.</p><div class="ability-economy-graphic core-action-economy"><div class="economy-node type-instinct"><small>ROUND TIMING</small><strong>CORE ACTION · INSTINCT</strong><span class="ability-cost-pill type-instinct">INSTINCT</span></div><div class="economy-node type-move"><small>ON TURN</small><strong>CORE ACTION · MOVE</strong><span class="ability-cost-pill type-move">MOVE</span></div><div class="economy-node type-combat"><small>ON TURN</small><strong>CORE ACTION · COMBAT</strong><span class="ability-cost-pill type-combat">COMBAT</span></div><div class="economy-node type-reactive"><small>WHEN TRIGGERED</small><strong>CORE ACTION · REACTION</strong><span class="ability-cost-pill type-reactive">REACTION</span></div></div><p>Each character has one Core Instinct, one Core Move, one Core Combat, and one Core Reaction opportunity per round. The Reaction Core Action is spent when that character resolves an eligible Reactive Ability.</p></article>
          <article id="abilities-how" class="fundamentals-rule-section"><h2>ABILITIES</h2><p>Abilities are rules a character gains from Traits, Talents, Spells, equipment, and other sources. An Ability can modify a Core Action, be resolved through a Core Action, or trigger from an event created during the same Ability Chain. Abilities do not begin their own chains; they build from the Core Action that started the chain, and each specific character’s copy of an Ability can resolve only once in that chain.</p><div class="ordered-flow"><div class="mini-rule-node core"><strong>Choose a Core Action</strong><small>Spend the matching Core Action opportunity.</small><span class="ability-cost-pill type-core">CORE ACTION</span></div><span class="flow-arrow" aria-hidden="true">→</span><div class="mini-rule-node modifier"><strong>Resolve Abilities</strong><small>Talent · Spell · Trait · Equipment</small><span class="ability-cost-pill type-reactive">ABILITY</span></div><span class="flow-arrow" aria-hidden="true">→</span><div class="mini-rule-node result"><strong>Finish the chain</strong><small>Stop when no unused Ability has a legal trigger.</small><span class="ability-cost-pill type-passive">END</span></div></div></article>
          <article id="abilities-example" class="fundamentals-rule-section"><h2>ACTION &amp; ABILITY EXAMPLE</h2><p>One Core Combat Action can lead into several Abilities without creating another Core Combat opportunity.</p><div class="ordered-flow"><div class="mini-rule-node magic"><strong>Arcane Command</strong><small>Selu spends the Core Combat Action and casts Ballad of the Courageous.</small><div class="keyword-pill-row"><span class="ability-cost-pill type-core">CORE ACTION</span><span class="ability-cost-pill type-combat">COMBAT</span><span class="ability-cost-pill type-magic">MAGIC</span></div></div><span class="flow-arrow" aria-hidden="true">→</span><div class="mini-rule-node spell"><strong>Ballad resolves</strong><small>The Spell is an Ability resolved through Arcane Command and grants its listed Enhance.</small><div class="keyword-pill-row"><span class="ability-cost-pill type-ability">ABILITY</span><span class="ability-cost-pill type-magic">MAGIC</span></div></div><span class="flow-arrow" aria-hidden="true">→</span><div class="mini-rule-node talent"><strong>Hearth Touch</strong><small>Because an Enhance was granted, Hearth Touch resolves from its trigger if it has not already resolved in this chain.</small><div class="keyword-pill-row"><span class="ability-cost-pill type-ability">ABILITY</span><span class="ability-cost-pill type-passive">PASSIVE</span><span class="ability-cost-pill type-magic">MAGIC</span></div></div></div></article>
          <article id="abilities-reactive" class="fundamentals-rule-section"><h2>REACTION EXAMPLE</h2><p>Brann uses Hero’s Charge and its movement satisfies an ally’s Pack Tactics Trigger. That ally may spend their Reaction Core Action to resolve Pack Tactics, then the original Ability Chain continues.</p><div class="ordered-flow"><div class="mini-rule-node core"><strong>Hero’s Charge</strong><small>Brann spends a Core Move Action and moves as part of the charge.</small><span class="ability-cost-pill type-move">CORE ACTION</span></div><span class="flow-arrow" aria-hidden="true">→</span><div class="mini-rule-node reactive"><strong>Reaction</strong><small>Pack Tactics is now eligible, so the ally spends their Reaction Core Action.</small><span class="ability-cost-pill type-reactive">REACTION</span></div><span class="flow-arrow" aria-hidden="true">→</span><div class="mini-rule-node ally"><strong>Pack Tactics</strong><small>The ally resolves the Reactive Ability once, then the same Ability Chain continues.</small><div class="keyword-pill-row"><span class="ability-cost-pill type-ability">ABILITY</span><span class="ability-cost-pill type-reactive">REACTIVE</span></div></div></div></article>
          <article id="abilities-chaining" class="fundamentals-rule-section"><h2>CHAINING ABILITIES</h2><p>An Ability Chain begins with a Core Action and continues while its results create legal Ability triggers. Reactions from the acting character, allies, and enemies can join the same chain through each character’s own Reaction Core Action.</p><div class="chaining-grid"><div class="chaining-step"><span class="chaining-step-number">1</span><div class="mini-rule-node core"><strong>Hero’s Charge</strong><small>Brann begins with the Hero’s Charge Core Action.</small><div class="keyword-pill-row"><span class="ability-cost-pill type-core">CORE ACTION</span><span class="ability-cost-pill type-move">MOVE</span></div></div></div><div class="chaining-step"><span class="chaining-step-number">2</span><div class="mini-rule-node modifier"><strong>Heroic Surge</strong><small>A compatible Charge Ability builds from the Core Action.</small><div class="keyword-pill-row"><span class="ability-cost-pill type-ability">ABILITY</span><span class="ability-cost-pill type-move">MOVE</span></div></div></div><div class="chaining-step"><span class="chaining-step-number">3</span><div class="mini-rule-node reactive"><strong>Reaction</strong><small>An ally’s Pack Tactics Trigger becomes legal, so that ally spends their Reaction Core Action.</small><span class="ability-cost-pill type-reactive">CORE ACTION</span></div></div><div class="chaining-step"><span class="chaining-step-number">4</span><div class="mini-rule-node ally"><strong>Pack Tactics</strong><small>The ally resolves Pack Tactics once in this chain and shifts into position.</small><div class="keyword-pill-row"><span class="ability-cost-pill type-ability">ABILITY</span><span class="ability-cost-pill type-reactive">REACTIVE</span></div></div></div><div class="chaining-step"><span class="chaining-step-number">5</span><div class="mini-rule-node reactive"><strong>Reaction</strong><small>The targeted enemy has Stillroot available and spends their own Reaction Core Action.</small><span class="ability-cost-pill type-reactive">CORE ACTION</span></div></div><div class="chaining-step"><span class="chaining-step-number">6</span><div class="mini-rule-node enemy"><strong>Stillroot</strong><small>The enemy resolves Stillroot once for this Ability Chain.</small><div class="keyword-pill-row"><span class="ability-cost-pill type-ability">ABILITY</span><span class="ability-cost-pill type-reactive">REACTIVE</span></div></div></div><div class="chaining-step"><span class="chaining-step-number">7</span><div class="mini-rule-node reactive"><strong>Reaction</strong><small>A second ally has Pouncer available and spends that character’s Reaction Core Action.</small><span class="ability-cost-pill type-reactive">CORE ACTION</span></div></div><div class="chaining-step"><span class="chaining-step-number">8</span><div class="mini-rule-node ally"><strong>Pouncer</strong><small>Pouncer resolves once if its Ward-failure Trigger is satisfied.</small><div class="keyword-pill-row"><span class="ability-cost-pill type-ability">ABILITY</span><span class="ability-cost-pill type-reactive">REACTIVE</span></div></div></div><div class="chaining-step"><span class="chaining-step-number">9</span><div class="mini-rule-node result"><strong>Chain ends</strong><small>When no unresolved Ability instance has a legal Trigger, the Ability Chain ends.</small><span class="ability-cost-pill type-passive">END</span></div></div></div><div class="chain-resolution-note card-surface"><strong>Once per Ability Chain:</strong><span>A specific character’s copy of an Ability can resolve only once during the same Ability Chain. If another character possesses the same named Ability, that is a separate Ability instance and may resolve once in that chain as well.</span></div></article>
          <article id="abilities-core" class="fundamentals-rule-section"><h2>CORE ACTIONS</h2><p>These are the shared Core Actions that begin Ability Chains or provide universal encounter responses.</p><details class="core-action-catalog" open><summary>Complete Core Action List <span>{{ coreActions.length }} actions</span></summary><div class="core-action-grid"><article v-for="action in coreActions" :key="action.name" class="trait-card core-action-card" :class="coreActionCardClass(action.keywords)"><div class="trait-card-head"><div><h3>{{ action.name }}</h3><small>Core Action</small></div><span v-if="action.cost" class="mana-badge">{{ action.cost }}</span></div><p class="rule-flavor"><em>{{ action.flavor }}</em></p><div class="rule-breakdown-grid"><div v-for="field in action.fields" :key="field.label"><small>{{ field.label }}</small><span>{{ field.value }}</span></div></div><div class="keyword-pill-row"><span v-for="keyword in action.keywords" :key="keyword" :class="ABILITY_TYPE_KEYWORDS.has(canonicalAbilityType(keyword))?['ability-cost-pill',abilityTypeClass(keyword)]:'keyword-pill'">{{ coreActionKeywordLabel(action.name,keyword) }}</span></div></article></div></details></article>
        </section>

        <article v-for="(section,index) in bodySections" v-else :id="sectionId(section.heading,index)" :key="`${section.heading}-${index}`" class="fundamentals-rule-section">
          <h2>{{ displayHeading(section.heading) }}</h2>
          <figure v-if="mode==='core'&&section.heading==='THE CORE ROLL'" class="fundamentals-rule-dice"><img :src="diceStrip" alt="Illustrated polyhedral dice" /></figure>
          <template v-if="showSecondaryStatsGraphic(section)"><p class="secondary-stats-summary">Secondary stats are derived values tied to an Attribute. A secondary stat uses either that Attribute’s Rank or its modifier; its rule tells you which value applies.</p><div class="attribute-breakdown-graphic"><article v-for="item in secondaryBreakdown" :key="item.short" class="attribute-breakdown-card"><header><strong>{{ item.name }}</strong><small>{{ item.short }}</small></header><div><span>Rank</span><b>→</b><strong>{{ item.rank }}</strong></div><div><span>Modifier</span><b>→</b><strong>{{ item.modifier }}</strong></div><small v-if="item.extra">{{ item.extra }}</small></article></div></template>
          <template v-for="(block,blockIndex) in section.blocks" :key="blockIndex">
            <div v-if="isFormulaParagraph(section,block)" class="core-roll-formula">3d10 + Stat + Conditions</div>
            <p v-else-if="block.type==='paragraph'&&!isHalfStepFormula(block)">{{ displayParagraph(section,block.text) }}</p>
            <div v-else-if="block.type==='paragraph'" class="half-step-rule-graphic"><div class="half-step-roll-node"><small>Roll one die</small><strong>d10</strong></div><span class="half-step-arrow">↓</span><div class="half-step-band-grid"><div class="half-step-band-node"><small>Natural result</small><strong>1–5</strong><b>→ 1</b></div><div class="half-step-band-node"><small>Natural result</small><strong>6–10</strong><b>→ 2</b></div></div><small class="half-step-read-note">Read the natural die result by band. Do not divide the number shown on the die.</small></div>
            <article v-else-if="skillTreeName(block)" class="skill-tree-card" :class="`skill-tree-${skillTreeTone(skillTreeName(block))}`"><header><strong>{{ skillTreeName(block) }}</strong><small>Skill · Description · Example</small></header><div class="skill-tree-list"><div v-for="(row,rowIndex) in skillTreeRows(block)" :key="rowIndex"><strong>{{ displayText(row[0]||'') }}</strong><span>{{ displayText(row[1]||'') }}</span><small>{{ displayText(row[2]||'') }}</small></div></div></article>
            <div v-else class="fundamentals-table-wrap" :class="{'target-example-table':isTargetSection(section)}"><table><tbody><tr v-for="(row,rowIndex) in tableRows(section,block)" :key="rowIndex"><td v-for="(cell,cellIndex) in row" :key="cellIndex">{{ displayText(cell) }}</td></tr></tbody></table></div>
            <div v-if="showConditionsGraphic(section,blockIndex)" class="condition-process"><div class="condition-node bonus"><small>Condition</small><strong>High Ground</strong><b>+1</b></div><span>+</span><div class="condition-node bonus"><small>Condition</small><strong>Fortune</strong><b>+2</b></div><span>+</span><div class="condition-node penalty"><small>Condition</small><strong>Obscured</strong><b>−1</b></div><span>=</span><div class="condition-node total"><small>Total Modifier</small><strong>Conditions</strong><b>+2</b></div></div>
          </template>
          <div v-if="showEdgedWeightedGraphic(section)" class="edge-weight-example-grid"><article><h3>Edged Roll</h3><div class="example-dice"><span class="dropped">2</span><span>5</span><span>7</span><span>9</span></div><small>Drop the lowest die.</small><strong>5 + 7 + 9 = 21</strong></article><article><h3>Weighted Roll</h3><div class="example-dice"><span>2</span><span>5</span><span>7</span><span class="dropped">9</span></div><small>Drop the highest die.</small><strong>2 + 5 + 7 = 14</strong></article></div>
          <div v-if="showFortuneGraphic(section)" class="fortune-example-grid"><article><h3>Fortune Example</h3><div class="example-dice"><span class="fortune">9</span><span class="fortune">8</span><span>5</span></div><strong>2 Fortune → +2 Conditions</strong></article><article><h3>Misfortune Example</h3><div class="example-dice"><span class="misfortune">1</span><span class="misfortune">2</span><span>6</span></div><strong>2 Misfortune → −2 Conditions</strong></article></div>
          <article v-if="showHalfStepExample(section)" class="talent-half-step-example"><span class="eyebrow">CURRENT TALENT EXAMPLE</span><h3>Threadseer</h3><p><strong>Cooldown:</strong> [1d10/2+1]. Roll the d10, convert 1–5 to a half-step result of 1 or 6–10 to a result of 2, then add the listed +1 condition.</p><div class="half-step-math"><span class="math-die"><small>d10</small><b>8</b></span><span class="math-operator">→</span><span class="math-result"><small>6–10</small><b>2</b></span><span class="math-operator">+1</span><span class="math-result final"><small>Final</small><b>3</b></span></div></article>
        </article>
      </section>
      <nav v-if="previousPage||nextPage" class="fundamentals-page-nav card-surface"><RouterLink v-if="previousPage" class="secondary-button" :to="previousPage.path">← {{ previousPage.label }}</RouterLink><span></span><RouterLink v-if="nextPage" class="secondary-button" :to="nextPage.path">{{ nextPage.label }} →</RouterLink></nav>
      <nav class="fundamentals-contents card-surface"><h2>Contents</h2><div v-if="mode==='abilities'" class="fundamentals-links"><a href="#abilities-what">Core Actions &amp; Abilities</a><a href="#abilities-how">Abilities</a><a href="#abilities-example">Action &amp; Ability Example</a><a href="#abilities-reactive">Reaction Example</a><a href="#abilities-chaining">Chaining Abilities</a><a href="#abilities-core">Core Actions</a></div><div v-else class="fundamentals-links"><a v-for="(section,index) in bodySections" :key="`${section.heading}-${index}`" :href="`#${sectionId(section.heading,index)}`">{{ displayHeading(section.heading) }}</a></div></nav>
    </article>
  </main>
